import { chromium } from '@playwright/test'

const BASE = 'http://127.0.0.1:8092/'
const out = process.argv[2] || 'shot.png'
const url = process.argv[3] || (BASE + '?portal=houses&view=grid&buildingId=2118233910730670082&detail=house')

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } })
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE-ERR', m.text().slice(0, 200)) })
try {
  await page.goto(url, { waitUntil: 'networkidle', timeout: 45000 })
} catch (e) { console.log('goto warn', e.message) }
await page.waitForTimeout(4000)
// dump dialog text
const dialogText = await page.evaluate(() => {
  const el = document.querySelector('.portal-house-overview')
  return el ? el.innerText : (document.querySelector('.portal-detail-dialog') ? document.querySelector('.portal-detail-dialog').innerText.slice(0,400) : 'NO DIALOG')
})
console.log('DIALOG_TEXT:', JSON.stringify(dialogText))
await page.screenshot({ path: out, fullPage: false })
await browser.close()
console.log('saved', out)

