import { chromium } from '@playwright/test'

const BASE = 'http://127.0.0.1:8092/'
const out = process.argv[2] || 'shot.png'
const mode = process.argv[3] || 'direct' // direct | click
const PROJECT_ID = '2117907355055759362'
const BUILDING_ID = '2118233910730670082'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } })
page.on('pageerror', (e) => console.log('PAGE-ERR', String(e).slice(0, 160)))

// dismiss any ele-message-box that may appear (config error dialog)
async function closeDialogs() {
  try {
    const btn = page.locator('.el-message-box__btns button, .el-message-box__headerbtn')
    const cnt = await btn.count()
    for (let i = 0; i < cnt; i++) { try { await btn.nth(i).click({ timeout: 800 }) } catch {} }
  } catch {}
}

if (mode === 'direct') {
  const url = `${BASE}?portal=houses&view=grid&projectId=${PROJECT_ID}&buildingId=${BUILDING_ID}&detail=house`
  console.log('URL', url)
  try { await page.goto(url, { waitUntil: 'sessionidle', timeout: 45000 }) } catch (e) { console.log('goto', e.message) }
  await page.waitForTimeout(2500)
  await closeDialogs()
  await page.waitForTimeout(1500)
} else {
  // interact: go to projects list -> 可售楼盘 -> open project -> buildings -> grid -> click room
  const url = `${BASE}?portal=projects&view=buildings&projectId=${PROJECT_ID}`
  console.log('URL', url)
  try { await page.goto(url, { waitUntil: 'sessionidle', timeout: 45000 }) } catch (e) { console.log('goto', e.message) }
  await page.waitForTimeout(3000)
  await closeDialogs()
  await page.waitForTimeout(1000)
  // click 16号楼 building link
  const b16 = page.getByText('16号楼', { exact: true }).first()
  try { await b16.click({ timeout: 4000 }) } catch (e) { console.log('b16 click fail', e.message) }
  await page.waitForTimeout(2500)
  await closeDialogs()
  // click 封闭空间 room
  const room = page.locator('.property-room', { hasText: '封闭空间' }).first()
  const cnt = await room.count()
  console.log('封闭空间 room count', cnt)
  if (cnt) { try { await room.click({ timeout: 4000 }) } catch (e) { console.log('room click fail', e.message) } }
  await page.waitForTimeout(2500)
}

const info = await page.evaluate(() => {
  const body = document.querySelector('.portal-house-overview')
  const dialog = document.querySelector('.portal-detail-dialog')
  const rows = Array.from(document.querySelectorAll('.portal-house-overview > div')).map((d) => {
    const label = d.querySelector('label')
    const val = d.querySelector('span') || d.querySelector('strong')
    const cs = val ? getComputedStyle(val) : null
    const ls = label ? getComputedStyle(label) : null
    return {
      label: label ? label.innerText : '',
      value: val ? val.innerText : '',
      valFont: cs ? `${cs.fontSize}/${cs.fontWeight}` : '',
      labelFont: ls ? `${ls.fontSize}/${ls.fontWeight}` : '',
      valTop: val ? Math.round(val.getBoundingClientRect().top) : null,
      labTop: label ? Math.round(label.getBoundingClientRect().top) : null,
      labLeft: label ? Math.round(label.getBoundingClientRect().left) : null
    }
  })
  return { hasOverview: !!body, hasDialog: !!dialog, rows }
})
console.log('INFO', JSON.stringify(info, null, 2))
await page.screenshot({ path: out })
await browser.close()
console.log('saved', out)

