async function closeDialogs() {
  for (let round = 0; round < 3; round++) {
    const btns = page.locator('.el-message-box__btns button, .el-message-box__headerbtn')
    const cnt = await btns.count()
    if (!cnt) return
    for (let i = 0; i < cnt; i++) { try { await btns.nth(i).click({ timeout: 500 }) } catch {} }
    await page.waitForTimeout(300)
  }
}
async function clickText(t) {
  const loc = page.getByText(t, { exact: true }).first()
  try { await loc.click({ timeout: 6000 }); return true } catch (e) { console.log('click fail:', t, e.message.split('\n')[0]); return false }
}

