await page.waitForTimeout(2500)
await closeDialogs()
console.log('after building url', page.url())
await page.screenshot({ path: out.replace('.png', '-s3.png') })

// click 封闭空间 room
const room = page.locator('.property-room', { hasText: '封闭空间' }).first()
const rc = await room.count()
console.log('room count', rc)
if (rc) { try { await room.click({ timeout: 5000 }) } catch (e) { console.log('room click fail', e.message.split('\n')[0]) } }
await page.waitForTimeout(2500)
await closeDialogs()

const info = await page.evaluate(() => {
  const rows = Array.from(document.querySelectorAll('.portal-house-overview > div')).map((d) => {
    const label = d.querySelector('label')
    const val = d.querySelector('span') || d.querySelector('strong')
    const cs = val ? getComputedStyle(val) : null
    const ls = label ? getComputedStyle(label) : null
    const vr = val ? val.getBoundingClientRect() : null
    const lr = label ? label.getBoundingClientRect() : null
    return {
      label: label ? label.innerText : '',
      value: val ? val.innerText : '',
      valFont: cs ? `${cs.fontSize} w${cs.fontWeight}` : '',
      labelFont: ls ? `${ls.fontSize} w${ls.fontWeight}` : '',
      valTop: vr ? Math.round(vr.top) : null,
      labTop: lr ? Math.round(lr.top) : null,
      valLeft: vr ? Math.round(vr.left) : null,
      labLeft: lr ? Math.round(lr.left) : null
    }
  })
  return { hasOverview: rows.length > 0, rows }
})
console.log('INFO', JSON.stringify(info, null, 2))
await page.screenshot({ path: out })
await browser.close()
console.log('saved', out)

